package com.timachado.brothermatrizes.desktop.platform

import java.net.URI

/**
 * Offline contract check for the Google PKCE redirect prepared by Windows.
 *
 * This verifies only the address shape generated by this application.
 * It CANNOT read or approve Supabase Authentication > Redirect URLs.
 * Never use this result to authorize an account, quotas or font imports.
 */
internal object DesktopPkceRedirectPreflight {
    /**
     * CANDIDATE for manual Supabase Dashboard review only.
     * The question mark is escaped: in Supabase's documented glob syntax
     * an unescaped ? means one arbitrary non-separator character.
     * The * segments support the ephemeral local port and randomized state.
     */
    const val SUPABASE_ALLOWLIST_CANDIDATE =
        """http://127.0.0.1:*/brother-matrizes/auth\?bm_state=*"""

    private val stateQuery = Regex("""bm_state=[A-Za-z0-9_-]{43}""")

    fun generatedRedirectHasExpectedShape(redirect: URI): Boolean =
        redirect.scheme == "http" &&
            redirect.host == "127.0.0.1" &&
            redirect.port in 1024..65535 &&
            redirect.rawUserInfo == null &&
            redirect.rawPath == "/brother-matrizes/auth" &&
            redirect.rawFragment == null &&
            redirect.rawQuery?.matches(stateQuery) == true
}
